export function checkENVRuntime(host,u,prefix,events){u.root;tick(host);const a=u.envAssembly,rest=physical(u),ports=frames(u),n=events.length;assert.ok(a.input.port===u.get('grove'));for(const k of['sensor','component','button','led','joint','display','speaker','imu'])assert.equal(own(u,k).length,0);for(const type of['temperature','humidity','pressure','sampling','sensor','read','i2c','address','register','firmware','led','button','joint'])assert.throws(()=>host.handle({type,target:target(prefix,'grove'),value:1,angleDeg:30}));assert.equal(events.length,n);assert.equal(physical(u),rest);assert.equal(frames(u),ports);host.update(.4);assert.equal(events.length,n,'No invented automatic readings/glow/sampling/input echo');assert.equal(physical(u),rest);assert.equal(frames(u),ports);return{staticActualCasePcbPackagesContacts:true,noEnvironmentalReadingsSamplingI2cRegistersPowerFirmware:true,noAutomaticLightsMotionOrInputEcho:true,allPhysicalAttributesIndicesWorldRetained:true,ownControls:0,ownLeds:0,ownJoints:0,noSensorAnchor:true};}

